using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Entities;using Microsoft.EntityFrameworkCore;namespace JobOrbit.Infrastructure.Persistence.Repositories;public sealed class HiringManagerSettingsRepository(JobOrbitDbContext db):IHiringManagerSettingsRepository{public Task<HiringManagerProfile?>GetAsync(int id,CancellationToken t=default)=>db.HiringManagerProfiles.Include(x=>x.User).Include(x=>x.Organization).Include(x=>x.Department).SingleOrDefaultAsync(x=>x.UserId==id&&x.User.IsActive,t);public Task SaveAsync(CancellationToken t=default)=>db.SaveChangesAsync(t);}
